import AdminOffres from "@/pages/admin/AdminOffres";
import AdminFormOffre from "@/pages/admin/AdminFormOffre";
import OffreSuccess from "@/pages/admin/OffreSuccess";
import { FilePlus } from "lucide-react";

const offresRoutes = [
  { path: "offres", element: <AdminOffres />, label: "Offres", icon: <FilePlus />, superAdmin: false },
  { path: "offres/ajouter", element: <AdminFormOffre /> },
  { path: "offres/modifier", element: <AdminFormOffre /> },
  { path: "offres/success", element: <OffreSuccess /> },
];

export default offresRoutes;
