// 📁 src/components/admin/ExportButtons.jsx
import { Download, FileText, FileDown } from "lucide-react";

export default function ExportButtons({ onPdf, onCsv, size = "sm", className = "" }) {
  const base =
    "inline-flex items-center gap-1 rounded px-3 py-1 text-white disabled:opacity-50";
  const sm = size === "sm" ? "text-sm" : "";

  return (
    <div className={`flex gap-2 ${className}`}>
      <button
        onClick={onPdf}
        className={`${base} ${sm} bg-blue-600 hover:bg-blue-700`}
        aria-label="Exporter en PDF"
      >
        <FileText size={16} /> PDF
      </button>
      <button
        onClick={onCsv}
        className={`${base} ${sm} bg-green-600 hover:bg-green-700`}
        aria-label="Exporter en CSV"
      >
        <FileDown size={16} /> CSV
      </button>
    </div>
  );
}
