// 📁 src/hooks/usePdfExport.js
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

export default function usePdfExport(ref, { title = "Rapport", header = "", filePrefix = "export" } = {}) {
  const exportPDF = async () => {
    if (!ref?.current) return;
    const el = ref.current;
    const canvas = await html2canvas(el, {
      scale: 2,
      useCORS: true,
      allowTaint: true,
      backgroundColor: "#ffffff",
      logging: false,
    });

    const img = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");
    const w = pdf.internal.pageSize.getWidth();
    const hPage = pdf.internal.pageSize.getHeight();
    const hImg = (canvas.height * w) / canvas.width;

    pdf.setFontSize(12);
    pdf.text(title, 14, 10);
    if (header) {
      pdf.setFontSize(10);
      pdf.text(header, 14, 16);
    }

    let pos = 20;
    let left = hImg;

    pdf.addImage(img, "PNG", 0, pos, w, hImg);
    left -= hPage;

    while (left > 0) {
      pdf.addPage();
      pdf.addImage(img, "PNG", 0, 0, w, hImg);
      left -= hPage;
    }

    const stamp = new Date().toISOString().slice(0, 10);
    pdf.save(`${filePrefix}-${stamp}.pdf`);
  };

  return { exportPDF };
}
