// src/components/layouts/MainLayout.jsx
import { useContext } from "react";
import { Outlet } from "react-router-dom";
import { ThemeContext } from "@/context/ThemeContext";
import Navbar from "@/components/Navbar"; // ✅ ajoute cette ligne

export default function MainLayout() {
  const { theme } = useContext(ThemeContext);

  return (
    <div className="min-h-screen flex flex-col">
      {/* ✅ Navbar globale (transparente sur accueil) */}
      <Navbar />

      {/* ✅ Contenu dynamique */}
      <main className="flex-grow">
        <Outlet />
      </main>

      {/* ✅ Footer global */}
      <footer className="bg-gray-100 dark:bg-gray-900 text-center text-sm py-4 text-gray-500 dark:text-gray-400">
        © {new Date().getFullYear()} CDO TCHAD. Tous droits réservés.
      </footer>
    </div>
  );
}
